cp "$ROOT/packaging/solarminer-update-check-daily" "$STAGE/usr/bin/solarminer-update-check-daily"
cp "$ROOT/packaging/solarminer-update-check-daily.service" "$STAGE/lib/systemd/system/solarminer-update-check-daily.service"
cp "$ROOT/packaging/solarminer-update-check-daily.timer" "$STAGE/lib/systemd/system/solarminer-update-check-daily.timer"
cp "$ROOT/packaging/solarminer-recovery.service" "$STAGE/lib/systemd/system/solarminer-recovery.service"
cp "$ROOT/packaging/solarminer-recovery.timer" "$STAGE/lib/systemd/system/solarminer-recovery.timer"
cp "$ROOT/packaging/solarminer-gateway.service" "$STAGE/lib/systemd/system/solarminer-gateway.service"
cp "$ROOT/packaging/solarminer-public-tls-renew" "$STAGE/usr/sbin/solarminer-public-tls-renew"
cp "$ROOT/packaging/solarminer-public-tls-renew.service" "$STAGE/lib/systemd/system/solarminer-public-tls-renew.service"
cp "$ROOT/packaging/solarminer-public-tls-renew.timer" "$STAGE/lib/systemd/system/solarminer-public-tls-renew.timer"
cp "$ROOT/packaging/solarminer-tailscale-info" "$STAGE/usr/sbin/solarminer-tailscale-info"
cp "$ROOT/packaging/solarminer-tailscale-info.sudoers" "$STAGE/etc/sudoers.d/solarminer-tailscale-info"
cp "$ROOT/packaging/solarminer-tailscale-connect" "$STAGE/usr/sbin/solarminer-tailscale-connect"
cp "$ROOT/packaging/solarminer-tailscale-connect.sudoers" "$STAGE/etc/sudoers.d/solarminer-tailscale-connect"
cp "$ROOT/packaging/solarminer-tailscale-cert" "$STAGE/usr/sbin/solarminer-tailscale-cert"
cp "$ROOT/packaging/solarminer-tailscale-cert.service" "$STAGE/lib/systemd/system/solarminer-tailscale-cert.service"
cp "$ROOT/packaging/solarminer-tailscale-cert.timer" "$STAGE/lib/systemd/system/solarminer-tailscale-cert.timer"
cp "$ROOT/packaging/install-tailscale.sh" "$STAGE/usr/share/solarminer/install-tailscale.sh"
cp "$ROOT/packaging/solarminer-gateway-nginx.conf" "$STAGE/usr/share/solarminer/nginx/solarminer-gateway.conf"
cp "$ROOT/src/solarminer_gateway/"*.py "$STAGE/usr/lib/solarminer-gateway/solarminer_gateway/"
cp "$ROOT/README.md" "$STAGE/usr/share/doc/solarminer-gateway/README.md"
cp "$ROOT/docs/TLS_TRUST.md" "$STAGE/usr/share/doc/solarminer-gateway/TLS_TRUST.md"
cp "$ROOT/docs/REMOTE_ACCESS_AND_TLS.md" "$STAGE/usr/share/doc/solarminer-gateway/REMOTE_ACCESS_AND_TLS.md"
