cp "$ROOT/docs/CODE02_CONNECTOR_MANAGER.md" "$STAGE/usr/share/doc/solarminer-gateway/CODE02_CONNECTOR_MANAGER.md"
cp "$ROOT/docs/deye/README.md" "$STAGE/usr/share/doc/solarminer-gateway/DEYE_MODBUS_READ_ONLY.md"
cp "$ROOT/docs/dependencies/README.md" "$STAGE/usr/share/doc/solarminer-gateway/CONNECTOR_DEPENDENCIES.md"
cp "$ROOT/docs/isolated-connectors.md" "$STAGE/usr/share/doc/solarminer-gateway/ISOLATED_CONNECTORS.md"
cp "$ROOT/docs/CODE02_V061_INSTALL_RECOVERY.md" "$STAGE/usr/share/doc/solarminer-gateway/INSTALL_RECOVERY_V061.md"
cp "$ROOT/docs/CODE02_V062_ENERGY_AND_WORKERS.md" "$STAGE/usr/share/doc/solarminer-gateway/ENERGY_AND_WORKERS_V062.md"
cp "$ROOT/docs/CODE02_V062_PHYSICAL_VALIDATION.md" "$STAGE/usr/share/doc/solarminer-gateway/PHYSICAL_VALIDATION_V062.md"
