cp "$ROOT/docs/PWA_GITHUB_PAGES.md" "$STAGE/usr/share/doc/solarminer-gateway/PWA_GITHUB_PAGES.md"
cp "$ROOT/docs/ACCEPTANCE_MATRIX_V069.md" "$STAGE/usr/share/doc/solarminer-gateway/ACCEPTANCE_MATRIX_V069.md"
cp "$ROOT/docs/TEST_REPORT_V069.md" "$STAGE/usr/share/doc/solarminer-gateway/TEST_REPORT_V069.md"
cp "$ROOT/docs/V069_LIMITATIONS.md" "$STAGE/usr/share/doc/solarminer-gateway/V069_LIMITATIONS.md"
cp "$ROOT/docs/PWA_V057_CHANGELOG.md" "$STAGE/usr/share/doc/solarminer-gateway/PWA_V057_CHANGELOG.md"
cp "$ROOT/docs/SOURCE_PROVENANCE.md" "$STAGE/usr/share/doc/solarminer-gateway/SOURCE_PROVENANCE.md"
cp "$ROOT/packaging/catalog/catalog.json" "$STAGE/usr/share/solarminer/catalog.json"
cp "$ROOT/packaging/catalog/catalog.sig" "$STAGE/usr/share/solarminer/catalog.sig"
cp "$ROOT/packaging/catalog/catalog.pub" "$STAGE/usr/share/solarminer/catalog.pub"
cp -R "$ROOT/web/pwa/." "$STAGE/usr/share/solarminer/pwa/"
chmod 0440 "$STAGE/etc/sudoers.d/solarminer-update-apply"
chmod 0755 "$STAGE/usr/sbin/solarminer-update-apply" "$STAGE/usr/sbin/solarminer-public-tls-renew" "$STAGE/usr/sbin/solarminer-tailscale-info" "$STAGE/usr/sbin/solarminer-tailscale-connect" "$STAGE/usr/sbin/solarminer-tailscale-cert" "$STAGE/usr/share/solarminer/install-tailscale.sh" "$STAGE/usr/bin/solarminer-update-check-daily" "$STAGE/DEBIAN/postinst" "$STAGE/DEBIAN/prerm" "$STAGE/DEBIAN/postrm" "$STAGE/usr/bin/solarminer-gateway" "$STAGE/usr/bin/solarminer-recovery"
chmod 0440 "$STAGE/etc/sudoers.d/solarminer-tailscale-info" "$STAGE/etc/sudoers.d/solarminer-tailscale-connect"
chmod 0644 "$STAGE/usr/share/solarminer/nginx/solarminer-gateway.conf" "$STAGE/usr/lib/solarminer-gateway/solarminer_gateway/"*.py "$STAGE/lib/systemd/system/solarminer-gateway.service" "$STAGE/lib/systemd/system/solarminer-public-tls-renew.service" "$STAGE/lib/systemd/system/solarminer-public-tls-renew.timer" "$STAGE/lib/systemd/system/solarminer-tailscale-cert.service" "$STAGE/lib/systemd/system/solarminer-tailscale-cert.timer" "$STAGE/lib/systemd/system/solarminer-recovery.service" "$STAGE/lib/systemd/system/solarminer-recovery.timer" "$STAGE/lib/systemd/system/solarminer-update-apply@.service" "$STAGE/lib/systemd/system/solarminer-update-check-daily.service" "$STAGE/lib/systemd/system/solarminer-update-check-daily.timer" "$STAGE/usr/share/solarminer/catalog.json" "$STAGE/usr/share/solarminer/catalog.sig" "$STAGE/usr/share/solarminer/catalog.pub"
find "$STAGE/usr/share/solarminer/pwa" -type d -exec chmod 0755 {} +
find "$STAGE/usr/share/solarminer/pwa" -type f -exec chmod 0644 {} +
PACKAGE_VERSION=$(sed -n 's/^Version: //p' "$ROOT/packaging/control")
case "$PACKAGE_VERSION" in
  ''|*[!0-9A-Za-z.+:~_-]*) echo "Invalid package version in packaging/control" >&2; exit 1 ;;
esac
OUTPUT="$OUT/solarminer-gateway_${PACKAGE_VERSION}_amd64.deb"
SOURCE_DATE_EPOCH=${SOURCE_DATE_EPOCH:-0} dpkg-deb --root-owner-group --build "$STAGE" "$OUTPUT"
